//! Domain types for a watch and its check state.

use std::collections::BTreeMap;
use std::fmt;
use std::str::FromStr;
use std::time::Duration;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::conditions::Conditions;
use crate::hash::ContentHash;
use crate::method::Method;
use crate::pipeline::Step;

/// Identifier of a watch (a UUID, v7 when generated by the store).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(transparent)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
#[cfg_attr(feature = "openapi", schema(value_type = Uuid))]
pub struct WatchId(Uuid);

/// The text is not a valid watch id.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("invalid watch id {0:?}")]
pub struct ParseWatchIdError(String);

impl WatchId {
    /// Wrap an existing UUID.
    pub fn from_uuid(uuid: Uuid) -> Self {
        Self(uuid)
    }

    /// The underlying UUID.
    pub fn as_uuid(&self) -> Uuid {
        self.0
    }
}

impl fmt::Display for WatchId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.hyphenated().fmt(f)
    }
}

impl FromStr for WatchId {
    type Err = ParseWatchIdError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Uuid::parse_str(s)
            .map(Self)
            .map_err(|_| ParseWatchIdError(s.to_owned()))
    }
}

/// When a watch is checked. Serialised as `{"interval":300}`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
pub enum Schedule {
    /// Check every N seconds.
    Interval(u64),
}

impl Schedule {
    /// The time between checks.
    pub fn interval(&self) -> Duration {
        match self {
            Self::Interval(secs) => Duration::from_secs(*secs),
        }
    }
}

/// How a fetched body is turned into the text that gets compared.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
pub enum Processor {
    /// Readable text: HTML is converted, anything else is used as is.
    #[default]
    Text,
    /// Pretty-printed JSON with sorted keys.
    Json,
    /// One stable block per feed item.
    Feed,
}

/// The stored processor name is unknown.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("unknown processor {0:?}")]
pub struct ParseProcessorError(String);

impl Processor {
    /// The name stored in the database.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Text => "text",
            Self::Json => "json",
            Self::Feed => "feed",
        }
    }
}

impl fmt::Display for Processor {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl FromStr for Processor {
    type Err = ParseProcessorError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "text" => Ok(Self::Text),
            "json" => Ok(Self::Json),
            "feed" => Ok(Self::Feed),
            other => Err(ParseProcessorError(other.to_owned())),
        }
    }
}

/// Per-watch HTTP settings. Every field is optional so `{}` is a valid value.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(default)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
pub struct FetchSettings {
    /// Request timeout in seconds; the global default applies when unset.
    pub timeout_secs: Option<u64>,
    /// `User-Agent` override.
    pub user_agent: Option<String>,
    /// Extra request headers.
    pub headers: BTreeMap<String, String>,
    /// The request method. Left out of the stored JSON when it is `GET`.
    #[serde(skip_serializing_if = "Method::is_default")]
    pub method: Method,
    /// The request body, sent as it is. Set `Content-Type` in `headers` when the server wants
    /// one. Left out of the stored JSON when unset.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub body: Option<String>,
}

/// A watch's request settings do not hold together.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum FetchSettingsError {
    /// A body was given with `GET`, which would not send it as a server expects.
    #[error("a request body needs POST, PUT, PATCH or DELETE, not GET")]
    BodyWithGet,
    /// The body is longer than [`FetchSettings::MAX_BODY_BYTES`].
    #[error("the request body is longer than 1 MiB")]
    BodyTooLarge,
}

impl FetchSettings {
    /// The longest request body, in bytes.
    pub const MAX_BODY_BYTES: usize = 1024 * 1024;

    /// Check that the settings go together.
    pub fn validate(&self) -> Result<(), FetchSettingsError> {
        match &self.body {
            Some(_) if self.method == Method::Get => Err(FetchSettingsError::BodyWithGet),
            Some(body) if body.len() > Self::MAX_BODY_BYTES => {
                Err(FetchSettingsError::BodyTooLarge)
            }
            _ => Ok(()),
        }
    }
}

/// What the last checks found. Times are unix milliseconds.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct WatchState {
    /// When the watch was last checked, successfully or not.
    pub last_checked_at: Option<i64>,
    /// When the content last changed.
    pub last_changed_at: Option<i64>,
    /// Message of the last failed check; cleared by the next success.
    pub last_error: Option<String>,
    /// Failed checks in a row.
    pub consecutive_errors: u32,
    /// Hash of the latest snapshot's text.
    pub last_hash: Option<ContentHash>,
    /// `ETag` of the last response, sent back as `If-None-Match`.
    pub etag: Option<String>,
    /// `Last-Modified` of the last response, sent back as `If-Modified-Since`.
    pub last_modified: Option<String>,
}

/// A monitored URL together with its configuration and state.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Watch {
    /// Unique id.
    pub id: WatchId,
    /// Display name.
    pub name: String,
    /// The URL to fetch.
    pub url: String,
    /// Paused watches are never scheduled.
    pub paused: bool,
    /// HTTP settings.
    pub fetch: FetchSettings,
    /// When to check.
    pub schedule: Schedule,
    /// Maximum random delay added to each run, in seconds; 0 means the scheduler default.
    pub jitter_secs: u32,
    /// How bodies are turned into text.
    pub processor: Processor,
    /// Steps applied after the processor, in order.
    pub pipeline: Vec<Step>,
    /// Which changes are worth a notification.
    pub conditions: Conditions,
    /// How many snapshots to keep.
    pub snapshot_retention: u32,
    /// Message template for this watch's notifications; it wins over the target's own.
    pub notification_template: Option<String>,
    /// Creation time, unix milliseconds.
    pub created_at: i64,
    /// Last modification time, unix milliseconds.
    pub updated_at: i64,
    /// Results of the most recent checks.
    pub state: WatchState,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn watch_id_round_trips_through_text() {
        let id = WatchId::from_uuid(Uuid::from_u128(0x0192_6f3a_1b2c_7d4e_8f90_a1b2_c3d4_e5f6));
        assert_eq!(id.to_string().parse::<WatchId>(), Ok(id));
    }

    #[test]
    fn watch_id_rejects_garbage() {
        assert!("nope".parse::<WatchId>().is_err());
    }

    #[test]
    fn schedule_matches_the_stored_json_shape() -> Result<(), serde_json::Error> {
        let schedule: Schedule = serde_json::from_str(r#"{"interval":300}"#)?;
        assert_eq!(schedule, Schedule::Interval(300));
        assert_eq!(schedule.interval(), Duration::from_secs(300));
        assert_eq!(serde_json::to_string(&schedule)?, r#"{"interval":300}"#);
        Ok(())
    }

    #[test]
    fn empty_fetch_settings_parse() -> Result<(), serde_json::Error> {
        let settings: FetchSettings = serde_json::from_str("{}")?;
        assert_eq!(settings, FetchSettings::default());
        Ok(())
    }

    #[test]
    fn method_and_body_are_left_out_of_the_stored_json_until_set() -> Result<(), serde_json::Error>
    {
        assert_eq!(
            serde_json::to_string(&FetchSettings::default())?,
            r#"{"timeout_secs":null,"user_agent":null,"headers":{}}"#
        );
        let settings: FetchSettings = serde_json::from_str(r#"{"method":"POST","body":"q=1"}"#)?;
        assert_eq!(
            (settings.method, settings.body.as_deref()),
            (Method::Post, Some("q=1"))
        );
        let stored = serde_json::to_string(&settings)?;
        assert!(
            stored.contains(r#""method":"POST""#) && stored.contains(r#""body":"q=1""#),
            "{stored}"
        );
        Ok(())
    }

    #[test]
    fn a_body_needs_a_method_that_carries_one() {
        let with = |method, body: Option<&str>| FetchSettings {
            method,
            body: body.map(str::to_owned),
            ..FetchSettings::default()
        };
        assert_eq!(with(Method::Get, None).validate(), Ok(()));
        assert_eq!(with(Method::Post, None).validate(), Ok(()));
        assert_eq!(with(Method::Post, Some("a=1")).validate(), Ok(()));
        assert_eq!(
            with(Method::Get, Some("a=1")).validate(),
            Err(FetchSettingsError::BodyWithGet)
        );
        let big = "x".repeat(FetchSettings::MAX_BODY_BYTES + 1);
        assert_eq!(
            with(Method::Put, Some(&big)).validate(),
            Err(FetchSettingsError::BodyTooLarge)
        );
    }

    #[test]
    fn processor_names_round_trip() {
        for p in [Processor::Text, Processor::Json, Processor::Feed] {
            assert_eq!(p.as_str().parse::<Processor>(), Ok(p));
        }
        assert!("xml".parse::<Processor>().is_err());
    }
}
